<!doctype html><html><head><meta charset="utf-8"><title><?= e($payment['receipt_number']) ?></title><style>body{font-family:DejaVu Sans,Arial,sans-serif;color:#172033;font-size:12px;margin:45px}*{box-sizing:border-box}.head{overflow:hidden;border-bottom:3px solid #0794b5;padding-bottom:18px}.brand{float:left;font-size:24px;font-weight:bold;color:#101936}.brand span{color:#0794b5}.doc{float:right;text-align:right}h1{font-size:22px;margin:0;color:#101936}.muted{color:#667085}.received{margin:35px 0;padding:25px;border:1px solid #d8e1ea;background:#f8fafc}.amount{font-size:28px;font-weight:bold;color:#15803d;margin:8px 0}.details{width:100%;border-collapse:collapse}.details td{padding:10px;border-bottom:1px solid #e4e7ec}.details td:first-child{color:#667085;width:38%}.foot{margin-top:55px;padding-top:15px;border-top:1px solid #e4e7ec;text-align:center;color:#667085}</style></head><body><div class="head"><div class="brand">Rankers <span>Mind</span><div class="muted" style="font-size:12px;font-weight:normal">Kolkata, West Bengal, India</div></div><div class="doc"><h1>PAYMENT RECEIPT</h1><strong><?= e($payment['receipt_number']) ?></strong></div></div><div class="received"><span class="muted">RECEIVED FROM</span><h2><?= e($payment['company_name']) ?></h2><div class="amount"><?= money($payment['amount']) ?></div><p>Payment received against invoice <strong><?= e($payment['invoice_number']) ?></strong>.</p></div><table class="details"><tr><td>Payment number</td><td><?= e($payment['payment_number']) ?></td></tr><tr><td>Payment date</td><td><?= e(date('d M Y',strtotime($payment['payment_date']))) ?></td></tr><tr><td>Payment mode</td><td><?= e($payment['payment_mode']) ?></td></tr><tr><td>Transaction/reference</td><td><?= e($payment['reference_number']?:'—') ?></td></tr><tr><td>Bank/account</td><td><?= e($payment['bank_account']?:'—') ?></td></tr><tr><td>Notes</td><td><?= nl2br(e($payment['notes']?:'—')) ?></td></tr></table><div class="foot">This computer-generated receipt does not require a signature.</div><script>if(!new URLSearchParams(location.search).has('format'))window.print()</script></body></html>
